import { useState, useEffect, useMemo } from "react";
import axios from "axios";
import { useWishlist } from "../context/WishlistContext";
import { useNavigate } from "react-router-dom";
import "./HouseCard.css"; // Import HouseCard.css

function HouseCard({ home, openChat }) {
  const { wishlist, addToWishlist, removeFromWishlist } = useWishlist();
  const [isInWishlist, setIsInWishlist] = useState(wishlist.includes(home.id));
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [paymentError, setPaymentError] = useState(null);
  const navigate = useNavigate();
  const [showCalendar, setShowCalendar] = useState(false);
  const [bookedDays, setBookedDays] = useState([]);
  const [selectedDates, setSelectedDates] = useState([]);
  const [averageRating, setAverageRating] = useState(null);
  const [userRating, setUserRating] = useState(0);
  const [hasBooked, setHasBooked] = useState(false);

  const images = useMemo(() => {
    let imgArray = [];
    try {
      if (typeof home.images === "string") {
        imgArray = JSON.parse(home.images);
        if (!Array.isArray(imgArray)) {
          imgArray = home.images.split(",");
        }
      } else if (Array.isArray(home.images)) {
        imgArray = home.images;
      }
    } catch (err) {
      imgArray = home.images.split(",");
    }
    return imgArray;
  }, [home.images]);

  useEffect(() => {
    if (images.length === 0) return;
    const interval = setInterval(() => {
      setCurrentImageIndex((prev) => (prev + 1) % images.length);
    }, 3000);
    return () => clearInterval(interval);
  }, [images]);

  useEffect(() => {
    // Fetch booked days for this home
    const fetchBookedDays = async () => {
      try {
        const response = await axios.get(
          `http://localhost:5000/api/bookings/${home.id}`
        );
        setBookedDays(response.data.bookedDays || []);
      } catch (error) {
        console.error("Error fetching booked days:", error);
      }
    };

    // Fetch average rating for this home
    const fetchAverageRating = async () => {
      try {
        const response = await axios.get(
          `http://localhost:5000/api/reviews/${home.id}/average`
        );
        setAverageRating(response.data.averageRating || null);
      } catch (error) {
        console.error("Error fetching average rating:", error);
      }
    };

    // Check if the user has booked this home
    const checkIfBooked = async () => {
      const userId = localStorage.getItem("userId");
      if (userId) {
        try {
          const response = await axios.get(
            `http://localhost:5000/api/bookings/check/${home.id}/${userId}`
          );
          setHasBooked(response.data.hasBooked);
        } catch (error) {
          console.error("Error checking booking status:", error);
        }
      }
    };

    fetchBookedDays();
    fetchAverageRating();
    checkIfBooked();
  }, [home.id]);

  const initializeRazorpay = () => {
    return new Promise((resolve) => {
      const script = document.createElement("script");
      script.src = "https://checkout.razorpay.com/v1/checkout.js";
      script.onload = () => resolve(true);
      script.onerror = () => resolve(false);
      document.body.appendChild(script);
    });
  };

  const handlePayment = async () => {
    const userId = localStorage.getItem("userId");
    if (!userId) {
      alert("Please log in to proceed with payment");
      return;
    }

    if (selectedDates.length === 0) {
      alert("Please select at least one date to book");
      return;
    }

    setPaymentError(null);

    try {
      const response = await axios.post("http://localhost:5000/api/order", {
        amount: home.price * selectedDates.length, // Price per day * number of days
        houseId: home.id,
        userId,
      });
      const { orderId, amount, currency } = response.data;

      const res = await initializeRazorpay();
      if (!res) {
        setPaymentError("Razorpay SDK failed to load. Please try again.");
        return;
      }

      const options = {
        key: process.env.REACT_APP_RAZORPAY_KEY_ID,
        amount,
        currency,
        name: "NestFinder",
        description: `Payment for ${home.address} (${selectedDates.length} days)`,
        order_id: orderId,
        handler: async function (response) {
          try {
            const verifyResponse = await axios.post(
              "http://localhost:5000/api/payment/verify",
              {
                razorpay_order_id: response.razorpay_order_id,
                razorpay_payment_id: response.razorpay_payment_id,
                razorpay_signature: response.razorpay_signature,
                houseId: home.id,
                userId,
                amount,
              }
            );
            if (verifyResponse.data.status === "success") {
              // Save bookings for each selected date
              for (const date of selectedDates) {
                const day = new Date(date).getDate();
                await axios.post(`http://localhost:5000/api/bookings`, {
                  houseId: home.id,
                  day,
                  amount: home.price,
                });
              }
              setHasBooked(true);
              setShowCalendar(false);
              setSelectedDates([]);
              navigate(
                `/booking-confirmation/${verifyResponse.data.bookingId}`
              );
            }
          } catch (error) {
            console.error("Payment verification failed:", error);
            setPaymentError(
              "Payment verification failed. Please try again or contact support."
            );
          }
        },
        prefill: {
          name: localStorage.getItem("full_name"),
          email: localStorage.getItem("email"),
        },
        theme: { color: "#3b82f6" },
      };

      const paymentObject = new window.Razorpay(options);
      paymentObject.open();
    } catch (error) {
      console.error("Payment initiation failed:", error);
      setPaymentError("Failed to initiate payment. Please try again.");
    }
  };

  const toggleWishlist = async () => {
    const userId = localStorage.getItem("userId");
    if (!userId) {
      alert("Please log in to add to wishlist");
      return;
    }

    try {
      if (isInWishlist) {
        await axios.delete("http://localhost:5000/wishlist/remove", {
          data: { userId, houseId: home.id },
          headers: { "Content-Type": "application/json" },
        });
        removeFromWishlist(home.id);
      } else {
        await axios.post("http://localhost:5000/wishlist/add", {
          userId,
          houseId: home.id,
        });
        addToWishlist(home.id);
      }
      setIsInWishlist(!isInWishlist);
    } catch (err) {
      console.error("Wishlist toggle failed:", err);
      alert("Failed to update wishlist");
    }
  };

  const handleBookClick = () => {
    const userId = localStorage.getItem("userId");
    if (!userId) {
      alert("Please log in to proceed with booking");
      return;
    }
    setShowCalendar(true);
  };

  const renderCalendar = () => {
    const today = new Date("2025-04-25"); // Current date as per instructions
    const daysInMonth = new Date(
      today.getFullYear(),
      today.getMonth() + 1,
      0
    ).getDate();
    const firstDayOfMonth = new Date(
      today.getFullYear(),
      today.getMonth(),
      1
    ).getDay();
    const days = [];

    // Add empty slots for days before the first day of the month
    for (let i = 0; i < firstDayOfMonth; i++) {
      days.push(<div key={`empty-${i}`} className="calendar-day"></div>);
    }

    // Add days of the month
    for (let day = 1; day <= daysInMonth; day++) {
      const currentDate = new Date(today.getFullYear(), today.getMonth(), day);
      const dateString = currentDate.toISOString().split("T")[0];
      const dayNumber = currentDate.getDate();
      const isBooked = bookedDays.includes(dayNumber);
      const isSelected = selectedDates.includes(dateString);
      const isPast = currentDate < today;

      days.push(
        <div
          key={day}
          className={`calendar-day ${isBooked ? "booked" : "available"} ${
            isSelected ? "selected" : ""
          }`}
          onClick={() => {
            if (isPast || isBooked) return; // Prevent selecting past or booked dates
            const newSelectedDates = [...selectedDates];
            const index = newSelectedDates.indexOf(dateString);
            if (index === -1) {
              newSelectedDates.push(dateString);
            } else {
              newSelectedDates.splice(index, 1);
            }
            setSelectedDates(newSelectedDates);
          }}
          style={{
            cursor: isPast || isBooked ? "not-allowed" : "pointer",
            textDecoration: isPast ? "none" : "underline",
            textDecorationColor: isBooked ? "#ff0000" : "#00ff00",
          }}
        >
          {day}
        </div>
      );
    }

    return (
      <div>
        <div className="calendar-grid">{days}</div>
        {selectedDates.length > 0 && (
          <button
            onClick={handlePayment}
            className="mt-4 px-4 py-2 bg-green-500 text-white rounded hover:bg-green-600"
          >
            Confirm Booking for {selectedDates.length} Day(s)
          </button>
        )}
      </div>
    );
  };

  const handleStarClick = async (rating) => {
    const userId = localStorage.getItem("userId");
    if (!userId) {
      alert("Please log in to submit a review");
      return;
    }

    try {
      await axios.post(`http://localhost:5000/api/reviews`, {
        houseId: home.id,
        userId,
        rating,
      });
      setUserRating(rating);
      const response = await axios.get(
        `http://localhost:5000/api/reviews/${home.id}/average`
      );
      setAverageRating(response.data.averageRating || null);
      alert("Review submitted successfully!");
    } catch (error) {
      console.error("Error submitting review:", error);
      alert("Failed to submit review. Please try again.");
    }
  };

  const renderStars = () => {
    const stars = [];
    for (let i = 1; i <= 5; i++) {
      stars.push(
        <span
          key={i}
          className={
            i <= (userRating || averageRating || 0)
              ? "star-filled"
              : "star-empty"
          }
          onClick={() => hasBooked && handleStarClick(i)}
          style={{ cursor: hasBooked ? "pointer" : "default" }}
        >
          ★
        </span>
      );
    }
    return stars;
  };

  const formattedPrice = (price) => {
    return price.toLocaleString("en-IN", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    });
  };

  return (
    <div
      style={{
        backgroundColor: "rgba(0, 0, 0, 0.6)",
        borderRadius: "1rem",
        boxShadow: "0 4px 6px rgba(0, 0, 0, 0.1)",
        display: "flex",
        flexDirection: "column",
        width: "600px",
        height: "550px",
        transition: "transform 0.2s",
        overflow: "hidden",
      }}
      onMouseOver={(e) =>
        (e.currentTarget.style.transform = "translateY(-4px)")
      }
      onMouseOut={(e) => (e.currentTarget.style.transform = "translateY(0)")}
    >
      <div
        className="slideshow-container"
        style={{
          width: "100%",
          height: "350px",
          overflow: "hidden",
          display: "block",
        }}
      >
        {images.map((img, i) => (
          <img
            key={i}
            src={`http://localhost:5000${img}`}
            alt="House"
            style={{
              display: i === currentImageIndex ? "block" : "none",
              width: "100%",
              height: "100%",
              objectFit: "cover",
              margin: "0",
            }}
          />
        ))}
      </div>
      <div
        style={{
          padding: "1.2rem",
          display: "flex",
          flexDirection: "column",
          flex: 1,
          justifyContent: "space-between",
        }}
      >
        <div>
          <h3
            style={{
              fontSize: "1.3rem",
              fontWeight: "600",
              color: "#ffffff",
              lineHeight: "1.5rem",
            }}
          >
            {home.address}
          </h3>
          <p
            style={{
              fontSize: "1rem",
              opacity: "0.9",
              color: "#ffffff",
              marginTop: "0.4rem",
            }}
          >
            <strong>Owner:</strong> {home.owner_name}
          </p>
          <p
            style={{
              fontSize: "1rem",
              opacity: "0.9",
              color: "#ffffff",
              marginTop: "0.3rem",
            }}
          >
            <strong>Contact:</strong> {home.contact}
          </p>
          <p
            style={{
              fontSize: "1rem",
              opacity: "0.9",
              color: "#ffffff",
              marginTop: "0.3rem",
            }}
          >
            <strong>Price:</strong> ₹{formattedPrice(home.price)}
          </p>
          <div className="flex items-center my-2">
            {renderStars()}
            <span className="ml-2 text-white opacity-90">
              ({averageRating || "0"}/5)
            </span>
          </div>
        </div>
        {paymentError && (
          <div className="text-red-500 text-center mb-4">
            <p>{paymentError}</p>
            <button
              onClick={handlePayment}
              className="mt-2 px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600"
            >
              Retry Payment
            </button>
          </div>
        )}
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            marginTop: "0.6rem",
            gap: "0.4rem",
          }}
        >
          <button
            onClick={handleBookClick}
            style={{
              flex: 1,
              padding: "0.6rem",
              backgroundColor: "#ffffff",
              color: "#000000",
              borderRadius: "0.5rem",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              gap: "0.4rem",
              fontSize: "1rem",
            }}
            onMouseOver={(e) =>
              (e.currentTarget.style.backgroundColor = "#e0e0e0")
            }
            onMouseOut={(e) =>
              (e.currentTarget.style.backgroundColor = "#ffffff")
            }
          >
            <img
              src={
                navigator.onLine
                  ? "http://localhost:5000/heart_raw.png"
                  : "/fallback-heart.jpg"
              }
              alt="pay"
              style={{ width: "1.4rem", height: "1.4rem" }}
              onError={(e) => {
                e.target.src = "/fallback-heart.jpg";
              }}
            />
            Book
          </button>
          <a
            href={`https://www.google.com/maps?q=${home.latitude},${home.longitude}`}
            target="_blank"
            rel="noopener noreferrer"
            style={{
              flex: 1,
              padding: "0.6rem",
              backgroundColor: "#8b5cf6",
              color: "#ffffff",
              borderRadius: "0.5rem",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              gap: "0.4rem",
              textDecoration: "none",
              fontSize: "1rem",
            }}
            onMouseOver={(e) =>
              (e.currentTarget.style.backgroundColor = "#7c3aed")
            }
            onMouseOut={(e) =>
              (e.currentTarget.style.backgroundColor = "#8b5cf6")
            }
          >
            <img
              src="http://localhost:5000/location_icon.jpg"
              alt="map"
              style={{ width: "1.4rem", height: "1.4rem" }}
            />
            Map
          </a>
          <button
            onClick={() => openChat(home.id, home.owner_name)}
            style={{
              flex: 1,
              padding: "0.6rem",
              backgroundColor: "#eab308",
              color: "#000000",
              borderRadius: "0.5rem",
              fontSize: "1rem",
            }}
            onMouseOver={(e) =>
              (e.currentTarget.style.backgroundColor = "#ca8a04")
            }
            onMouseOut={(e) =>
              (e.currentTarget.style.backgroundColor = "#eab308")
            }
          >
            <span style={{ fontSize: "1.2rem" }}>•</span> Chat
          </button>
          <button
            onClick={toggleWishlist}
            style={{
              flex: 1,
              padding: "0.6rem",
              backgroundColor: "#8b5cf6",
              color: "#ffffff",
              borderRadius: "0.5rem",
              fontSize: "1rem",
            }}
            onMouseOver={(e) =>
              (e.currentTarget.style.backgroundColor = "#7c3aed")
            }
            onMouseOut={(e) =>
              (e.currentTarget.style.backgroundColor = "#8b5cf6")
            }
          >
            {isInWishlist ? "Remove" : "Wishlist"}
          </button>
        </div>
      </div>

      {/* Calendar for selecting dates */}
      {showCalendar && (
        <div
          style={{
            position: "fixed",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            backgroundColor: "rgba(0, 0, 0, 0.5)",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            zIndex: 1000,
          }}
        >
          <div
            style={{
              backgroundColor: "white",
              padding: "2rem",
              borderRadius: "0.5rem",
              boxShadow: "0 4px 6px rgba(0, 0, 0, 0.1)",
              width: "400px",
              textAlign: "center",
            }}
          >
            <h4 style={{ fontSize: "1.5rem", marginBottom: "1rem" }}>
              Select Dates
            </h4>
            {renderCalendar()}
            <button
              onClick={() => {
                setShowCalendar(false);
                setSelectedDates([]);
              }}
              style={{
                marginTop: "1rem",
                padding: "0.5rem 1rem",
                backgroundColor: "#ef4444",
                color: "white",
                borderRadius: "0.3rem",
              }}
            >
              Close
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

export default HouseCard;
